window.LESSON_DATA = {"schemaVersion":"1.0.0","version":"1.0.1","buildDate":"2026-07-29","course":"IB Mathematics: Applications and Interpretation SL","unit":{"number":1,"title":"Number and Algebra"},"lesson":{"number":"1.3","slug":"geometric-sequences","title":"Geometric Sequences and Series","subtitle":"Model constant multiplicative change, growth and decay, and accumulated repeated effects.","syllabus_focus":"SL 1.3 — Geometric sequences and series; use of formulae for the nth term and sum of the first n terms; applications.","skill_keys":["IBAI.U1.SEQUENCES","IBAI.U1.MODELING"],"objectives":["Recognize constant ratio as geometric structure.","Use explicit and recursive geometric rules.","Calculate finite geometric sums and solve inverse problems.","Interpret growth and decay factors in authentic contexts."],"vocab":["common ratio","growth factor","decay factor","geometric sequence","geometric series","finite sum","exponential change"],"technology":"Generate a table and graph of \\(ar^n\\). Use logarithms or a solver to locate the first integer stage that crosses a threshold, then verify adjacent stages.","transition":"Geometric sequences and series remain part of the updated course."},"slides":[{"section":"Launch","title":"1.3 · Geometric Sequences and Series","html":"<div class=\"cover-grid\"><div><div class=\"cover-kicker\">IB DP Mathematics · Applications and Interpretation SL</div><h1><span class=\"cover-number\">1.3</span>Geometric Sequences and Series</h1><p class=\"cover-subtitle\">Model constant multiplicative change, growth and decay, and accumulated repeated effects.</p><div class=\"pill-row\"><span>Current syllabus</span><span>Technology-rich</span><span>Modelling</span><span>Original practice</span></div></div><svg class=\"concept-visual\" viewBox=\"0 0 520 180\" role=\"img\" aria-label=\"Geometric growth bars\"><rect width=\"520\" height=\"180\" rx=\"22\" fill=\"#F4EFE8\"/><text x=\"28\" y=\"30\" font-weight=\"800\" fill=\"#17324D\">Constant multiplicative change</text><rect x=\"46\" y=\"132\" width=\"42\" height=\"18\" rx=\"7\" fill=\"#177E89\" opacity=\".9\"/><rect x=\"114\" y=\"124\" width=\"42\" height=\"26\" rx=\"7\" fill=\"#D4A72C\" opacity=\".9\"/><rect x=\"182\" y=\"111\" width=\"42\" height=\"39\" rx=\"7\" fill=\"#7A1733\" opacity=\".9\"/><rect x=\"250\" y=\"92\" width=\"42\" height=\"58\" rx=\"7\" fill=\"#17324D\" opacity=\".9\"/><rect x=\"318\" y=\"63\" width=\"42\" height=\"87\" rx=\"7\" fill=\"#177E89\" opacity=\".9\"/><rect x=\"386\" y=\"20\" width=\"42\" height=\"130\" rx=\"7\" fill=\"#D4A72C\" opacity=\".9\"/><path d=\"M55 132 C180 120 280 88 430 26\" stroke=\"#7A1733\" stroke-width=\"4\" fill=\"none\"/><text x=\"405\" y=\"50\" fill=\"#177E89\">×r</text></svg></div>","kind":"cover","eyebrow":"Unit 1 · Number and Algebra"},{"section":"Launch","title":"Your place in Unit 1","html":"<div class=\"unit-map\"><div class=\"map-node \"><b>1.1</b><span>Scientific Notation and Orders of Magnitude</span></div><div class=\"map-node \"><b>1.2</b><span>Arithmetic Sequences and Series</span></div><div class=\"map-node active\"><b>1.3</b><span>Geometric Sequences and Series</span></div><div class=\"map-node \"><b>1.4</b><span>Financial Applications of Sequences</span></div><div class=\"map-node \"><b>1.5</b><span>Introduction to Logarithms</span></div><div class=\"map-node \"><b>1.6</b><span>Approximation, Bounds and Percentage Error</span></div><div class=\"map-node \"><b>1.7</b><span>Loans, Annuities and Amortization</span></div><div class=\"map-node \"><b>1.8</b><span>Technology for Equations and Systems</span></div></div><p class=\"callout\">The course moves from representation and discrete change to financial modelling, uncertainty and technology-based solution methods.</p>","kind":"content","eyebrow":""},{"section":"Launch","title":"Syllabus focus","html":"<div class=\"focus-card\"><h3>Current course alignment</h3><p>SL 1.3 — Geometric sequences and series; use of formulae for the nth term and sum of the first n terms; applications.</p><p><b>Platform mastery keys:</b> IBAI.U1.SEQUENCES, IBAI.U1.MODELING</p></div><div class=\"transition-note\">Geometric sequences and series remain part of the updated course.</div>","kind":"content","eyebrow":""},{"section":"Inquiry","title":"A question worth investigating","html":"<blockquote>Why does repeated percentage change behave differently from repeated addition?</blockquote><p>Record an initial response. Return to it at the end and identify how your reasoning changed.</p><textarea class=\"student-note\" data-note=\"inquiry\" aria-label=\"Inquiry response\"></textarea>","kind":"inquiry","eyebrow":""},{"section":"Inquiry","title":"Learning intentions","html":"<div class=\"two-col\"><div><h3>By the end, you can…</h3><ul class=\"check-list\"><li>Recognize constant ratio as geometric structure.</li><li>Use explicit and recursive geometric rules.</li><li>Calculate finite geometric sums and solve inverse problems.</li><li>Interpret growth and decay factors in authentic contexts.</li></ul></div><div><h3>Evidence of understanding</h3><ul class=\"check-list\"><li>Choose an efficient representation.</li><li>Use technology transparently.</li><li>Interpret rather than merely calculate.</li><li>Evaluate assumptions and precision.</li></ul></div></div>","kind":"content","eyebrow":""},{"section":"Diagnostic","title":"Prior-knowledge diagnostic","html":"<div class=\"student-turn\"><h3>Try before instruction</h3><p>A quantity changes \\(80,96,115.2,\\ldots\\). What multiplicative factor connects consecutive terms?</p><textarea class=\"student-note\" data-note=\"diagnostic\"></textarea><details><summary>Diagnostic lens</summary><p>Focus on structure, units and the meaning of the result—not just a final number.</p></details></div>","kind":"student","eyebrow":""},{"section":"Language","title":"Core vocabulary","html":"<div class=\"vocab-grid\"><div class=\"vocab-chip\">common ratio</div><div class=\"vocab-chip\">growth factor</div><div class=\"vocab-chip\">decay factor</div><div class=\"vocab-chip\">geometric sequence</div><div class=\"vocab-chip\">geometric series</div><div class=\"vocab-chip\">finite sum</div><div class=\"vocab-chip\">exponential change</div></div><p class=\"callout\">Use precise vocabulary in every explanation. In IB mathematics, communication earns meaning, not decoration.</p>","kind":"content","eyebrow":""},{"section":"Approach","title":"The AI modelling cycle","html":"<div class=\"cycle\"><div>Context</div><span>→</span><div>Assumptions</div><span>→</span><div>Mathematical form</div><span>→</span><div>Technology & computation</div><span>→</span><div>Interpretation</div><span>→</span><div>Validation & refinement</div></div><p>Every substantial task in this lesson returns to this cycle. A numerical answer without interpretation is unfinished.</p>","kind":"content","eyebrow":""},{"section":"Concept 1","title":"Constant multiplicative change","html":"<div class=\"concept-grid\"><div><p>A geometric sequence has a constant ratio between consecutive non-zero terms. The ratio can represent growth, decay or sign alternation.</p><div class=\"formula-panel\">\\[r=\\frac{u_{n+1}}{u_n}\\]</div></div><svg class=\"concept-visual\" viewBox=\"0 0 520 180\" role=\"img\" aria-label=\"Geometric growth bars\"><rect width=\"520\" height=\"180\" rx=\"22\" fill=\"#F4EFE8\"/><text x=\"28\" y=\"30\" font-weight=\"800\" fill=\"#17324D\">Constant multiplicative change</text><rect x=\"46\" y=\"132\" width=\"42\" height=\"18\" rx=\"7\" fill=\"#177E89\" opacity=\".9\"/><rect x=\"114\" y=\"124\" width=\"42\" height=\"26\" rx=\"7\" fill=\"#D4A72C\" opacity=\".9\"/><rect x=\"182\" y=\"111\" width=\"42\" height=\"39\" rx=\"7\" fill=\"#7A1733\" opacity=\".9\"/><rect x=\"250\" y=\"92\" width=\"42\" height=\"58\" rx=\"7\" fill=\"#17324D\" opacity=\".9\"/><rect x=\"318\" y=\"63\" width=\"42\" height=\"87\" rx=\"7\" fill=\"#177E89\" opacity=\".9\"/><rect x=\"386\" y=\"20\" width=\"42\" height=\"130\" rx=\"7\" fill=\"#D4A72C\" opacity=\".9\"/><path d=\"M55 132 C180 120 280 88 430 26\" stroke=\"#7A1733\" stroke-width=\"4\" fill=\"none\"/><text x=\"405\" y=\"50\" fill=\"#177E89\">×r</text></svg></div>","kind":"content","eyebrow":"Concept cycle 1 of 5"},{"section":"Concept 1","title":"Worked example · Constant multiplicative change","html":"<div class=\"worked\"><div class=\"prompt\"><span>Problem</span><p>Show that \\(160,120,90,67.5,\\ldots\\) is geometric.</p></div><div class=\"method\"><span>Reasoning</span><p>Each term is multiplied by \\(0.75\\), so \\(r=0.75\\).</p></div></div>","kind":"worked","eyebrow":""},{"section":"Concept 1","title":"Student turn","html":"<div class=\"student-turn\"><h3>Now transfer the idea</h3><p>Find the ratio of \\(5,-10,20,-40,\\ldots\\).</p><textarea class=\"student-note\" data-note=\"turn-1\"></textarea><details><summary>Reveal answer and check</summary><p>\\(r=-2\\).</p></details></div>","kind":"student","eyebrow":""},{"section":"Concept 1","title":"Explain the solution","html":"<div class=\"solution-panel\"><h3>Complete reasoning</h3><p>\\(r=-2\\).</p><div class=\"explain-prompt\">Which representation, formula or technology step made the solution efficient?</div></div>","kind":"solution","eyebrow":""},{"section":"Concept 1","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h3>Common trap</h3><p>A constant percentage change creates a constant ratio, not a constant difference.</p><p><b>Repair move:</b> test the claim with a simple value, units, substitution or a graph.</p></div></div>","kind":"misconception","eyebrow":""},{"section":"Concept 2","title":"The nth term","html":"<div class=\"concept-grid\"><div><p>From the first term to term \\(n\\), the ratio is applied \\(n-1\\) times.</p><div class=\"formula-panel\">\\[u_n=ar^{n-1}\\]</div></div><svg class=\"concept-visual\" viewBox=\"0 0 520 180\" role=\"img\" aria-label=\"Geometric growth bars\"><rect width=\"520\" height=\"180\" rx=\"22\" fill=\"#F4EFE8\"/><text x=\"28\" y=\"30\" font-weight=\"800\" fill=\"#17324D\">Constant multiplicative change</text><rect x=\"46\" y=\"132\" width=\"42\" height=\"18\" rx=\"7\" fill=\"#177E89\" opacity=\".9\"/><rect x=\"114\" y=\"124\" width=\"42\" height=\"26\" rx=\"7\" fill=\"#D4A72C\" opacity=\".9\"/><rect x=\"182\" y=\"111\" width=\"42\" height=\"39\" rx=\"7\" fill=\"#7A1733\" opacity=\".9\"/><rect x=\"250\" y=\"92\" width=\"42\" height=\"58\" rx=\"7\" fill=\"#17324D\" opacity=\".9\"/><rect x=\"318\" y=\"63\" width=\"42\" height=\"87\" rx=\"7\" fill=\"#177E89\" opacity=\".9\"/><rect x=\"386\" y=\"20\" width=\"42\" height=\"130\" rx=\"7\" fill=\"#D4A72C\" opacity=\".9\"/><path d=\"M55 132 C180 120 280 88 430 26\" stroke=\"#7A1733\" stroke-width=\"4\" fill=\"none\"/><text x=\"405\" y=\"50\" fill=\"#177E89\">×r</text></svg></div>","kind":"content","eyebrow":"Concept cycle 2 of 5"},{"section":"Concept 2","title":"Worked example · The nth term","html":"<div class=\"worked\"><div class=\"prompt\"><span>Problem</span><p>For \\(a=6,r=1.4\\), find \\(u_8\\).</p></div><div class=\"method\"><span>Reasoning</span><p>\\(u_8=6(1.4)^7\\approx63.25\\).</p></div></div>","kind":"worked","eyebrow":""},{"section":"Concept 2","title":"Student turn","html":"<div class=\"student-turn\"><h3>Now transfer the idea</h3><p>For \\(a=320,r=0.82\\), find \\(u_{10}\\).</p><textarea class=\"student-note\" data-note=\"turn-2\"></textarea><details><summary>Reveal answer and check</summary><p>\\(u_{10}=320(0.82)^9\\approx53.68\\).</p></details></div>","kind":"student","eyebrow":""},{"section":"Concept 2","title":"Explain the solution","html":"<div class=\"solution-panel\"><h3>Complete reasoning</h3><p>\\(u_{10}=320(0.82)^9\\approx53.68\\).</p><div class=\"explain-prompt\">Which representation, formula or technology step made the solution efficient?</div></div>","kind":"solution","eyebrow":""},{"section":"Concept 2","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h3>Common trap</h3><p>Use the unrounded ratio during calculation; early rounding compounds error.</p><p><b>Repair move:</b> test the claim with a simple value, units, substitution or a graph.</p></div></div>","kind":"misconception","eyebrow":""},{"section":"Concept 3","title":"Recovering a ratio","html":"<div class=\"concept-grid\"><div><p>Ratios of separated terms satisfy \\(u_q/u_p=r^{q-p}\\). A context may restrict the sign of \\(r\\).</p><div class=\"formula-panel\">\\[\\frac{u_q}{u_p}=r^{q-p}\\]</div></div><svg class=\"concept-visual\" viewBox=\"0 0 520 180\" role=\"img\" aria-label=\"Geometric growth bars\"><rect width=\"520\" height=\"180\" rx=\"22\" fill=\"#F4EFE8\"/><text x=\"28\" y=\"30\" font-weight=\"800\" fill=\"#17324D\">Constant multiplicative change</text><rect x=\"46\" y=\"132\" width=\"42\" height=\"18\" rx=\"7\" fill=\"#177E89\" opacity=\".9\"/><rect x=\"114\" y=\"124\" width=\"42\" height=\"26\" rx=\"7\" fill=\"#D4A72C\" opacity=\".9\"/><rect x=\"182\" y=\"111\" width=\"42\" height=\"39\" rx=\"7\" fill=\"#7A1733\" opacity=\".9\"/><rect x=\"250\" y=\"92\" width=\"42\" height=\"58\" rx=\"7\" fill=\"#17324D\" opacity=\".9\"/><rect x=\"318\" y=\"63\" width=\"42\" height=\"87\" rx=\"7\" fill=\"#177E89\" opacity=\".9\"/><rect x=\"386\" y=\"20\" width=\"42\" height=\"130\" rx=\"7\" fill=\"#D4A72C\" opacity=\".9\"/><path d=\"M55 132 C180 120 280 88 430 26\" stroke=\"#7A1733\" stroke-width=\"4\" fill=\"none\"/><text x=\"405\" y=\"50\" fill=\"#177E89\">×r</text></svg></div>","kind":"content","eyebrow":"Concept cycle 3 of 5"},{"section":"Concept 3","title":"Worked example · Recovering a ratio","html":"<div class=\"worked\"><div class=\"prompt\"><span>Problem</span><p>Given \\(u_3=20\\), \\(u_7=320\\), find a positive \\(r\\).</p></div><div class=\"method\"><span>Reasoning</span><p>\\(r^4=16\\Rightarrow r=2\\); then \\(a=5\\).</p></div></div>","kind":"worked","eyebrow":""},{"section":"Concept 3","title":"Student turn","html":"<div class=\"student-turn\"><h3>Now transfer the idea</h3><p>Given \\(u_2=12\\), \\(u_5=96\\), find the positive ratio.</p><textarea class=\"student-note\" data-note=\"turn-3\"></textarea><details><summary>Reveal answer and check</summary><p>\\(r^3=8\\Rightarrow r=2\\).</p></details></div>","kind":"student","eyebrow":""},{"section":"Concept 3","title":"Explain the solution","html":"<div class=\"solution-panel\"><h3>Complete reasoning</h3><p>\\(r^3=8\\Rightarrow r=2\\).</p><div class=\"explain-prompt\">Which representation, formula or technology step made the solution efficient?</div></div>","kind":"solution","eyebrow":""},{"section":"Concept 3","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h3>Common trap</h3><p>If the context allows negative ratios, an even power can lead to more than one algebraic possibility.</p><p><b>Repair move:</b> test the claim with a simple value, units, substitution or a graph.</p></div></div>","kind":"misconception","eyebrow":""},{"section":"Concept 4","title":"Finite geometric series","html":"<div class=\"concept-grid\"><div><p>Subtracting \\(rS_n\\) from \\(S_n\\) cancels interior terms and produces the finite sum formula.</p><div class=\"formula-panel\">\\[S_n=a\\frac{1-r^n}{1-r}\\quad(r\\ne1)\\]</div></div><svg class=\"concept-visual\" viewBox=\"0 0 520 180\" role=\"img\" aria-label=\"Geometric growth bars\"><rect width=\"520\" height=\"180\" rx=\"22\" fill=\"#F4EFE8\"/><text x=\"28\" y=\"30\" font-weight=\"800\" fill=\"#17324D\">Constant multiplicative change</text><rect x=\"46\" y=\"132\" width=\"42\" height=\"18\" rx=\"7\" fill=\"#177E89\" opacity=\".9\"/><rect x=\"114\" y=\"124\" width=\"42\" height=\"26\" rx=\"7\" fill=\"#D4A72C\" opacity=\".9\"/><rect x=\"182\" y=\"111\" width=\"42\" height=\"39\" rx=\"7\" fill=\"#7A1733\" opacity=\".9\"/><rect x=\"250\" y=\"92\" width=\"42\" height=\"58\" rx=\"7\" fill=\"#17324D\" opacity=\".9\"/><rect x=\"318\" y=\"63\" width=\"42\" height=\"87\" rx=\"7\" fill=\"#177E89\" opacity=\".9\"/><rect x=\"386\" y=\"20\" width=\"42\" height=\"130\" rx=\"7\" fill=\"#D4A72C\" opacity=\".9\"/><path d=\"M55 132 C180 120 280 88 430 26\" stroke=\"#7A1733\" stroke-width=\"4\" fill=\"none\"/><text x=\"405\" y=\"50\" fill=\"#177E89\">×r</text></svg></div>","kind":"content","eyebrow":"Concept cycle 4 of 5"},{"section":"Concept 4","title":"Worked example · Finite geometric series","html":"<div class=\"worked\"><div class=\"prompt\"><span>Problem</span><p>Find the sum of the first 12 terms of \\(a=50,r=0.9\\).</p></div><div class=\"method\"><span>Reasoning</span><p>\\(S_{12}=50\\frac{1-0.9^{12}}{0.1}\\approx358.79\\).</p></div></div>","kind":"worked","eyebrow":""},{"section":"Concept 4","title":"Student turn","html":"<div class=\"student-turn\"><h3>Now transfer the idea</h3><p>Find \\(S_9\\) for \\(a=3,r=2\\).</p><textarea class=\"student-note\" data-note=\"turn-4\"></textarea><details><summary>Reveal answer and check</summary><p>\\(S_9=3(2^9-1)=1533\\).</p></details></div>","kind":"student","eyebrow":""},{"section":"Concept 4","title":"Explain the solution","html":"<div class=\"solution-panel\"><h3>Complete reasoning</h3><p>\\(S_9=3(2^9-1)=1533\\).</p><div class=\"explain-prompt\">Which representation, formula or technology step made the solution efficient?</div></div>","kind":"solution","eyebrow":""},{"section":"Concept 4","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h3>Common trap</h3><p>The finite formula works for growth and decay; an infinite-sum formula is a different result and is not needed here.</p><p><b>Repair move:</b> test the claim with a simple value, units, substitution or a graph.</p></div></div>","kind":"misconception","eyebrow":""},{"section":"Concept 5","title":"Growth, decay and model validation","html":"<div class=\"concept-grid\"><div><p>Write the multiplier directly: a \\(p\\%\\) increase uses \\(1+p/100\\); a decrease uses \\(1-p/100\\). Define whether the initial value is term 0 or term 1.</p><div class=\"formula-panel\">\\[Q_t=Q_0(1\\pm p)^t\\]</div></div><svg class=\"concept-visual\" viewBox=\"0 0 520 180\" role=\"img\" aria-label=\"Geometric growth bars\"><rect width=\"520\" height=\"180\" rx=\"22\" fill=\"#F4EFE8\"/><text x=\"28\" y=\"30\" font-weight=\"800\" fill=\"#17324D\">Constant multiplicative change</text><rect x=\"46\" y=\"132\" width=\"42\" height=\"18\" rx=\"7\" fill=\"#177E89\" opacity=\".9\"/><rect x=\"114\" y=\"124\" width=\"42\" height=\"26\" rx=\"7\" fill=\"#D4A72C\" opacity=\".9\"/><rect x=\"182\" y=\"111\" width=\"42\" height=\"39\" rx=\"7\" fill=\"#7A1733\" opacity=\".9\"/><rect x=\"250\" y=\"92\" width=\"42\" height=\"58\" rx=\"7\" fill=\"#17324D\" opacity=\".9\"/><rect x=\"318\" y=\"63\" width=\"42\" height=\"87\" rx=\"7\" fill=\"#177E89\" opacity=\".9\"/><rect x=\"386\" y=\"20\" width=\"42\" height=\"130\" rx=\"7\" fill=\"#D4A72C\" opacity=\".9\"/><path d=\"M55 132 C180 120 280 88 430 26\" stroke=\"#7A1733\" stroke-width=\"4\" fill=\"none\"/><text x=\"405\" y=\"50\" fill=\"#177E89\">×r</text></svg></div>","kind":"content","eyebrow":"Concept cycle 5 of 5"},{"section":"Concept 5","title":"Worked example · Growth, decay and model validation","html":"<div class=\"worked\"><div class=\"prompt\"><span>Problem</span><p>A device worth QAR 6200 depreciates by 18% yearly. Find its value after 4 years.</p></div><div class=\"method\"><span>Reasoning</span><p>\\(6200(0.82)^4\\approx\\text{QAR }2801.83\\).</p></div></div>","kind":"worked","eyebrow":""},{"section":"Concept 5","title":"Student turn","html":"<div class=\"student-turn\"><h3>Now transfer the idea</h3><p>A culture starts with 450 cells and grows by 12% per hour. Model the count after \\(t\\) hours.</p><textarea class=\"student-note\" data-note=\"turn-5\"></textarea><details><summary>Reveal answer and check</summary><p>\\(N(t)=450(1.12)^t\\).</p></details></div>","kind":"student","eyebrow":""},{"section":"Concept 5","title":"Explain the solution","html":"<div class=\"solution-panel\"><h3>Complete reasoning</h3><p>\\(N(t)=450(1.12)^t\\).</p><div class=\"explain-prompt\">Which representation, formula or technology step made the solution efficient?</div></div>","kind":"solution","eyebrow":""},{"section":"Concept 5","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h3>Common trap</h3><p>A 12% increase is multiplication by 1.12, not by 0.12.</p><p><b>Repair move:</b> test the claim with a simple value, units, substitution or a graph.</p></div></div>","kind":"misconception","eyebrow":""},{"section":"Technology","title":"Interactive exploration","html":"<div id=\"lesson-lab\" class=\"lab\" data-lab=\"1.3\"></div><p class=\"lab-note\">Change more than one input. Predict before pressing calculate, then explain what stays invariant.</p>","kind":"lab","eyebrow":""},{"section":"Technology","title":"Transparent technology workflow","html":"<div class=\"workflow\"><div><b>1</b> Define variables and domain</div><div><b>2</b> Enter the mathematical model</div><div><b>3</b> Choose an appropriate tool</div><div><b>4</b> Record settings/output</div><div><b>5</b> Verify independently</div><div><b>6</b> Interpret and round</div></div><p>Generate a table and graph of \\(ar^n\\). Use logarithms or a solver to locate the first integer stage that crosses a threshold, then verify adjacent stages.</p>","kind":"content","eyebrow":""},{"section":"Application","title":"Global and local context","html":"<div class=\"context-card\"><span>Context challenge</span><p>Compare two sustainability interventions: one saves a fixed amount each month, the other reduces usage by a fixed percentage. Decide when each model is more realistic.</p></div><textarea class=\"student-note tall\" data-note=\"context\"></textarea>","kind":"student","eyebrow":""},{"section":"Inquiry","title":"Mini-investigation","html":"<div class=\"investigation\"><h3>Question → evidence → conclusion</h3><p>Track a repeated multiplicative process, estimate a ratio from data, graph residuals, and evaluate whether a constant ratio is defensible.</p><ul class=\"check-list\"><li>State the question and variables.</li><li>Record assumptions and data sources.</li><li>Show mathematics and technology output.</li><li>Interpret, evaluate and refine.</li></ul></div>","kind":"investigation","eyebrow":""},{"section":"Assessment","title":"IB command terms","html":"<div class=\"command-grid\"><div><b>Write down</b><span>Give the result with little or no working.</span></div><div><b>Calculate</b><span>Show enough method for the result to be reproducible.</span></div><div><b>Determine</b><span>Reach a result with supporting reasoning.</span></div><div><b>Explain</b><span>Give causes, mechanisms or mathematical meaning.</span></div><div><b>Interpret</b><span>Translate mathematics back into context.</span></div><div><b>Comment</b><span>Make a judgement supported by evidence.</span></div></div>","kind":"content","eyebrow":""},{"section":"Assessment","title":"Equipment depreciation","html":"<div class=\"task-preview\"><div class=\"task-meta\"><span>Paper 1-style short response</span><span>9 marks</span><span>GDC expected</span></div><h3>Equipment depreciation</h3><p>A piece of equipment is purchased for QAR 24,000 and retains 82% of its value each year.</p><div class=\"task-part\"><b>(a)</b> Write a model for the value after \\(n\\) years. <span class=\"marks\">[2]</span></div><div class=\"task-part\"><b>(b)</b> Find the value after 6 years. <span class=\"marks\">[2]</span></div><div class=\"task-part\"><b>(c)</b> Find the first complete year in which the value is below QAR 8000. <span class=\"marks\">[3]</span></div><div class=\"task-part\"><b>(d)</b> Interpret the ratio 0.82 in context. <span class=\"marks\">[2]</span></div></div>","kind":"exam","eyebrow":""},{"section":"Assessment","title":"Equipment depreciation · markscheme","html":"<div class=\"task-preview solution-preview\"><h3>Equipment depreciation — worked markscheme</h3><div class=\"solution-part\"><b>(a) \\(V_n=24000(0.82)^n\\)</b><p>M1 identifies multiplier; A1 correct model/index.</p></div><div class=\"solution-part\"><b>(b) QAR 7,296.16</b><p>M1 substitutes; A1 correct currency value.</p></div><div class=\"solution-part\"><b>(c) 6 years</b><p>M1 forms/solves inequality; A1 continuous threshold; A1 checks first integer year.</p></div><div class=\"solution-part\"><b>(d) Each year the equipment retains 82% and loses 18% of the previous year’s value.</b><p>A1 retention; A1 loss is based on current value.</p></div></div>","kind":"solution","eyebrow":""},{"section":"Assessment","title":"Restoration programme","html":"<div class=\"task-preview\"><div class=\"task-meta\"><span>Paper 2-style extended response</span><span>12 marks</span><span>GDC expected</span></div><h3>Restoration programme</h3><p>A restoration programme plants 600 trees in year 1. Each later year it plants 1.12 times the previous year’s number.</p><div class=\"task-part\"><b>(a)</b> Find the planned number in year 8. <span class=\"marks\">[2]</span></div><div class=\"task-part\"><b>(b)</b> Find the total planned over the first 8 years. <span class=\"marks\">[3]</span></div><div class=\"task-part\"><b>(c)</b> In practice, capacity is limited to 1200 trees in any one year. Find the first year the unrestricted model exceeds capacity. <span class=\"marks\">[3]</span></div><div class=\"task-part\"><b>(d)</b> From that year onward, suppose planting remains at 1200 per year. Find the revised total for the first 12 years. <span class=\"marks\">[3]</span></div><div class=\"task-part\"><b>(e)</b> State one limitation of assuming a constant 12% increase. <span class=\"marks\">[1]</span></div></div>","kind":"exam","eyebrow":""},{"section":"Assessment","title":"Restoration programme · markscheme","html":"<div class=\"task-preview solution-preview\"><h3>Restoration programme — worked markscheme</h3><div class=\"solution-part\"><b>(a) 1326.41 trees</b><p>M1 nth-term formula; A1 value.</p></div><div class=\"solution-part\"><b>(b) 7379.82 trees</b><p>M1 geometric-sum formula; M1 substitution; A1 value.</p></div><div class=\"solution-part\"><b>(c) Year 8</b><p>M1 solves \\(600(1.12)^{n-1}>1200\\); A1 threshold; A1 checks adjacent years.</p></div><div class=\"solution-part\"><b>(d) 12053.41 trees</b><p>M1 sums unrestricted years before cap; M1 adds capped years; A1 total.</p></div><div class=\"solution-part\"><b>(e) Land, staff, budget or seedling supply may constrain growth.</b><p>A1 relevant contextual limitation.</p></div></div>","kind":"solution","eyebrow":""},{"section":"Connections","title":"Where this mathematics connects","html":"<div class=\"connection-grid\"><div>Exponential functions</div><div>Compound interest</div><div>Population models</div><div>Percentage change</div></div><p>Write one sentence describing a connection you did not see at the start.</p><textarea class=\"student-note\" data-note=\"connection\"></textarea>","kind":"content","eyebrow":""},{"section":"Synthesis","title":"Five ideas to retain","html":"<ul class=\"check-list\"><li>Constant multiplicative change: A geometric sequence has a constant ratio between consecutive non-zero terms.</li><li>The nth term: From the first term to term \\(n\\), the ratio is applied \\(n-1\\) times.</li><li>Recovering a ratio: Ratios of separated terms satisfy \\(u_q/u_p=r^{q-p}\\).</li><li>Finite geometric series: Subtracting \\(rS_n\\) from \\(S_n\\) cancels interior terms and produces the finite sum formula.</li><li>Growth, decay and model validation: Write the multiplier directly: a \\(p\\%\\) increase uses \\(1+p/100\\); a decrease uses \\(1-p/100\\).</li></ul>","kind":"summary","eyebrow":""},{"section":"Reflection","title":"Return to the inquiry question","html":"<blockquote>Why does repeated percentage change behave differently from repeated addition?</blockquote><textarea class=\"student-note tall\" data-note=\"reflection\"></textarea><div class=\"reflection-grid\"><label><input type=\"checkbox\" data-reflect=\"model\"> I can model</label><label><input type=\"checkbox\" data-reflect=\"calculate\"> I can calculate</label><label><input type=\"checkbox\" data-reflect=\"interpret\"> I can interpret</label><label><input type=\"checkbox\" data-reflect=\"evaluate\"> I can evaluate</label></div>","kind":"reflection","eyebrow":""},{"section":"Exit","title":"Exit ticket","html":"<div class=\"exit-grid\"><div><b>One calculation</b><p>Create and solve a new example using today’s central formula.</p></div><div><b>One explanation</b><p>Describe a common error and how to detect it.</p></div><div><b>One evaluation</b><p>State one assumption that could change a conclusion.</p></div></div><textarea class=\"student-note tall\" data-note=\"exit\"></textarea>","kind":"student","eyebrow":""},{"section":"Next","title":"Practice Studio","html":"<div class=\"launch-panel\"><h2>40 original questions</h2><p>Four levels: Foundation, Application, Reasoning and Challenge. Every item includes marks, calculator guidance, hints and a complete solution.</p><button class=\"route-jump\" data-go=\"practice\">Open Practice Studio</button></div>","kind":"launch","eyebrow":""},{"section":"Next","title":"Independent timed quiz","html":"<div class=\"launch-panel\"><h2>10 fresh questions</h2><p>Complete the quiz under a suggested 25-minute timer, then review explanations and update your mastery reflection.</p><button class=\"route-jump\" data-go=\"quiz\">Start timed quiz</button></div>","kind":"launch","eyebrow":""},{"section":"Next","title":"Authenticated question-bank bridge","html":"<div class=\"bank-bridge\"><h2>More practice on the platform</h2><p>This lesson maps to <code>IBAI.U1.SEQUENCES, IBAI.U1.MODELING</code>. The attached private banks stay inside authenticated school access; no private prompt is copied into this public lesson file.</p><a href=\"https://2ed944-cloud.github.io/ECHS-Math/question-bank/practice.html?course=ib-math-ai&unit=1&lesson=1.3\" class=\"button-link\">Open additional bank practice</a></div>","kind":"launch","eyebrow":""}],"practice":[{"id":"IBAI-1.3-P01","level":"Foundation","prompt":"For a geometric sequence with \\(u_1=3\\) and \\(r=2\\), find \\(u_{8}\\).","answer":"\\(384\\)","solution":"Use \\(u_n=ar^{n-1}\\): \\(3(2)^{7}=384\\).","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["nth term"],"check":{"mode":"number","value":384,"tolerance":1e-06}},{"id":"IBAI-1.3-P02","level":"Foundation","prompt":"For a geometric sequence with \\(u_1=160\\) and \\(r=0.75\\), find \\(u_{7}\\).","answer":"\\(28.476562\\)","solution":"Use \\(u_n=ar^{n-1}\\): \\(160(0.75)^{6}=28.476562\\).","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["nth term"],"check":{"mode":"number","value":28.4765625,"tolerance":0.05}},{"id":"IBAI-1.3-P03","level":"Foundation","prompt":"For a geometric sequence with \\(u_1=5\\) and \\(r=-2\\), find \\(u_{6}\\).","answer":"\\(-160\\)","solution":"Use \\(u_n=ar^{n-1}\\): \\(5(-2)^{5}=-160\\).","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["nth term"],"check":{"mode":"number","value":-160,"tolerance":1e-06}},{"id":"IBAI-1.3-P04","level":"Foundation","prompt":"For a geometric sequence with \\(u_1=120\\) and \\(r=1.1\\), find \\(u_{10}\\).","answer":"\\(282.953723\\)","solution":"Use \\(u_n=ar^{n-1}\\): \\(120(1.1)^{9}=282.953723\\).","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["nth term"],"check":{"mode":"number","value":282.95372292000025,"tolerance":0.5}},{"id":"IBAI-1.3-P05","level":"Foundation","prompt":"For a geometric sequence with \\(u_1=0.8\\) and \\(r=1.5\\), find \\(u_{9}\\).","answer":"\\(20.503125\\)","solution":"Use \\(u_n=ar^{n-1}\\): \\(0.8(1.5)^{8}=20.503125\\).","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["nth term"],"check":{"mode":"number","value":20.503125,"tolerance":0.05}},{"id":"IBAI-1.3-P06","level":"Foundation","prompt":"Find the common ratio of \\(4, 12, 36, 108,\\ldots\\).","answer":"\\(3\\)","solution":"Divide a term by the preceding term; each ratio is \\(3\\).","marks":2,"calculator":"Mental","command":"Find","hint":"","tags":["common ratio"],"check":{"mode":"number","value":3,"tolerance":1e-06}},{"id":"IBAI-1.3-P07","level":"Foundation","prompt":"Find the common ratio of \\(200, 100, 50, 25,\\ldots\\).","answer":"\\(0.5\\)","solution":"Divide a term by the preceding term; each ratio is \\(0.5\\).","marks":2,"calculator":"Mental","command":"Find","hint":"","tags":["common ratio"],"check":{"mode":"number","value":0.5,"tolerance":0.05}},{"id":"IBAI-1.3-P08","level":"Foundation","prompt":"Find the common ratio of \\(3, -6, 12, -24,\\ldots\\).","answer":"\\(-2\\)","solution":"Divide a term by the preceding term; each ratio is \\(-2\\).","marks":2,"calculator":"Mental","command":"Find","hint":"","tags":["common ratio"],"check":{"mode":"number","value":-2,"tolerance":1e-06}},{"id":"IBAI-1.3-P09","level":"Foundation","prompt":"Find the common ratio of \\(1.2, 1.8, 2.7, 4.05,\\ldots\\).","answer":"\\(1.5\\)","solution":"Divide a term by the preceding term; each ratio is \\(1.5\\).","marks":2,"calculator":"Mental","command":"Find","hint":"","tags":["common ratio"],"check":{"mode":"number","value":1.5,"tolerance":0.05}},{"id":"IBAI-1.3-P10","level":"Foundation","prompt":"Find the common ratio of \\(81, 27, 9, 3,\\ldots\\).","answer":"\\(0.333333\\)","solution":"Divide a term by the preceding term; each ratio is \\(0.333333\\).","marks":2,"calculator":"Mental","command":"Find","hint":"","tags":["common ratio"],"check":{"mode":"number","value":0.3333333333333333,"tolerance":0.0005}},{"id":"IBAI-1.3-P11","level":"Application","prompt":"Find \\(S_{7}\\) for a geometric sequence with \\(a=2\\), \\(r=3\\).","answer":"\\(2186\\)","solution":"Use \\(S_n=a\\frac{1-r^n}{1-r}\\). Substitution gives \\(2186\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["series"],"check":{"mode":"number","value":2186.0,"tolerance":1e-06}},{"id":"IBAI-1.3-P12","level":"Application","prompt":"Find \\(S_{10}\\) for a geometric sequence with \\(a=500\\), \\(r=0.8\\).","answer":"\\(2231.564544\\)","solution":"Use \\(S_n=a\\frac{1-r^n}{1-r}\\). Substitution gives \\(2231.564544\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["series"],"check":{"mode":"number","value":2231.5645440000003,"tolerance":5.0}},{"id":"IBAI-1.3-P13","level":"Application","prompt":"Find \\(S_{8}\\) for a geometric sequence with \\(a=4\\), \\(r=1.5\\).","answer":"\\(197.03125\\)","solution":"Use \\(S_n=a\\frac{1-r^n}{1-r}\\). Substitution gives \\(197.03125\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["series"],"check":{"mode":"number","value":197.03125,"tolerance":0.5}},{"id":"IBAI-1.3-P14","level":"Application","prompt":"Find \\(S_{12}\\) for a geometric sequence with \\(a=120\\), \\(r=0.6\\).","answer":"\\(299.346965\\)","solution":"Use \\(S_n=a\\frac{1-r^n}{1-r}\\). Substitution gives \\(299.346965\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["series"],"check":{"mode":"number","value":299.3469652992,"tolerance":0.5}},{"id":"IBAI-1.3-P15","level":"Application","prompt":"Find \\(S_{6}\\) for a geometric sequence with \\(a=5\\), \\(r=-2\\).","answer":"\\(-105\\)","solution":"Use \\(S_n=a\\frac{1-r^n}{1-r}\\). Substitution gives \\(-105\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["series"],"check":{"mode":"number","value":-105.0,"tolerance":1e-06}},{"id":"IBAI-1.3-P16","level":"Application","prompt":"A culture begins with 850 cells and grows by 18% each hour. Find the number after 9 hours.","answer":"\\(3770.1358\\)","solution":"The growth factor is 1.18, so \\(N=850(1.18)^9\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["context"],"check":{"mode":"number","value":3770.135780278628,"tolerance":5.0}},{"id":"IBAI-1.3-P17","level":"Application","prompt":"A laptop worth QAR 5400 depreciates by 22% annually. Find its value after 3 years.","answer":"\\(2562.5808\\)","solution":"The decay factor is 0.78, so \\(V=5400(0.78)^3\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["context"],"check":{"mode":"number","value":2562.5808,"tolerance":0.011}},{"id":"IBAI-1.3-P18","level":"Application","prompt":"A ball rebounds to 72% of its previous height. From 2.5 m, find the height after the fifth bounce.","answer":"\\(0.4837\\)","solution":"Taking the initial height at bounce 0 gives \\(h_5=2.5(0.72)^5\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["context"],"check":{"mode":"number","value":0.4837294079999999,"tolerance":0.0005}},{"id":"IBAI-1.3-P19","level":"Application","prompt":"A social campaign reaches 120 people in its first round and 1.6 times as many in each later round. Find the total reached in the first 6 rounds.","answer":"\\(3155.4432\\)","solution":"Use a geometric sum with \\(a=120,r=1.6,n=6\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["context"],"check":{"mode":"number","value":3155.4432000000006,"tolerance":5e-05}},{"id":"IBAI-1.3-P20","level":"Application","prompt":"A medication amount is 400 mg initially and 65% remains each hour. Find the amount after 8 hours.","answer":"\\(12.7458\\)","solution":"\\(A=400(0.65)^8\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["context"],"check":{"mode":"number","value":12.745792515625004,"tolerance":0.05}},{"id":"IBAI-1.3-P21","level":"Reasoning","prompt":"Given \\(u_3=20\\) and \\(u_7=320\\) in a positive geometric sequence, find \\(r\\).","answer":"\\(2\\)","solution":"\\(u_7/u_3=r^4=16\\), so the positive ratio is 2.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["reverse reasoning"],"check":{"mode":"number","value":2,"tolerance":1e-06}},{"id":"IBAI-1.3-P22","level":"Reasoning","prompt":"A positive geometric sequence has \\(u_3=20\\) and \\(u_7=320\\). Find \\(u_1\\).","answer":"\\(5\\)","solution":"\\(u_3=ar^2\\), so \\(a=20/4=5\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["reverse reasoning"],"check":{"mode":"number","value":5,"tolerance":1e-06}},{"id":"IBAI-1.3-P23","level":"Reasoning","prompt":"Which term of \\(3,6,12,\\ldots\\) is 1536?","answer":"\\(10\\)","solution":"Solve \\(3(2)^{n-1}=1536\\). Since \\(1536/3=512=2^9\\), \\(n=10\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["reverse reasoning"],"check":{"mode":"number","value":10,"tolerance":1e-06}},{"id":"IBAI-1.3-P24","level":"Reasoning","prompt":"A geometric sequence has \\(u_2=18\\) and \\(u_5=486\\). Find the positive ratio.","answer":"\\(3\\)","solution":"\\(u_5/u_2=r^3=27\\), so \\(r=3\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["reverse reasoning"],"check":{"mode":"number","value":3,"tolerance":1e-06}},{"id":"IBAI-1.3-P25","level":"Reasoning","prompt":"How many terms of \\(200,160,128,\\ldots\\) are at least 20?","answer":"\\(11\\)","solution":"Solve \\(200(0.8)^{n-1}\\ge20\\). The first term below 20 is term 12, so 11 terms qualify.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["reverse reasoning"],"check":{"mode":"number","value":11,"tolerance":1e-06}},{"id":"IBAI-1.3-P26","level":"Reasoning","prompt":"A quantity triples every 4 hours. Find the equivalent hourly growth factor.","answer":"\\(1.316074\\)","solution":"If \\(r^4=3\\), then \\(r=3^{1/4}\\approx1.3161\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["reverse reasoning"],"check":{"mode":"number","value":1.3160740129524924,"tolerance":0.005}},{"id":"IBAI-1.3-P27","level":"Reasoning","prompt":"A geometric sequence has \\(S_5=93\\), \\(a=3\\), and positive integer ratio. Find \\(r\\).","answer":"\\(2\\)","solution":"\\(3(1+r+r^2+r^3+r^4)=93\\), so the bracket is 31, giving \\(r=2\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["reverse reasoning"],"check":{"mode":"number","value":2,"tolerance":1e-06}},{"id":"IBAI-1.3-P28","level":"Reasoning","prompt":"A machine retains 85% of its value each year. After how many complete years is it first worth less than half its initial value?","answer":"\\(5\\)","solution":"Solve \\(0.85^t<0.5\\). The continuous threshold is about 4.27 years, so after 5 complete years.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["reverse reasoning"],"check":{"mode":"number","value":5,"tolerance":1e-06}},{"id":"IBAI-1.3-P29","level":"Reasoning","prompt":"A real geometric sequence has \\(u_1=64\\) and \\(u_4=1\\). Find its common ratio.","answer":"\\(0.25\\)","solution":"\\(r^3=1/64\\), hence \\(r=1/4\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["reverse reasoning"],"check":{"mode":"number","value":0.25,"tolerance":0.005}},{"id":"IBAI-1.3-P30","level":"Reasoning","prompt":"If \\(u_4=54\\) and \\(u_7=1458\\), find the positive ratio.","answer":"\\(3\\)","solution":"\\(u_7/u_4=r^3=27\\), so \\(r=3\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["reverse reasoning"],"check":{"mode":"number","value":3,"tolerance":1e-06}},{"id":"IBAI-1.3-P31","level":"Challenge","prompt":"A viral post is shared by 3 people in round 1 and each participant creates 2.4 new shares in the next round. Find the total shares over 8 rounds.","answer":"\\(2356.61388\\)","solution":"Use \\(S_8=3(1-2.4^8)/(1-2.4)\\).","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","modelling"],"check":{"mode":"number","value":2356.6138751999993,"tolerance":5e-06}},{"id":"IBAI-1.3-P32","level":"Challenge","prompt":"A reservoir loses 6% of its water weekly. How many complete weeks until less than 40% remains?","answer":"\\(15\\)","solution":"Solve \\(0.94^t<0.40\\). The threshold is \\(t>14.81\\), so 15 complete weeks.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","modelling"],"check":{"mode":"number","value":15,"tolerance":1e-06}},{"id":"IBAI-1.3-P33","level":"Challenge","prompt":"A geometric sequence has positive terms, \\(u_2+u_3=30\\), and \\(u_4+u_5=270\\). Find \\(r\\).","answer":"\\(3\\)","solution":"Factor: \\(ar(1+r)=30\\) and \\(ar^3(1+r)=270\\). Division gives \\(r^2=9\\); positivity gives \\(r=3\\).","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","modelling"],"check":{"mode":"number","value":3,"tolerance":1e-06}},{"id":"IBAI-1.3-P34","level":"Challenge","prompt":"An investment doubles in 9 years under a constant annual growth factor. Find the annual percentage rate.","answer":"\\(8.00597\\)","solution":"\\(r=2^{1/9}\\); percentage rate \\((r-1)100\\approx8.006\\%\\).","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","modelling"],"check":{"mode":"number","value":8.00597388923061,"tolerance":0.005}},{"id":"IBAI-1.3-P35","level":"Challenge","prompt":"A sequence has \\(S_n=2046\\), \\(a=2\\), \\(r=2\\). Find \\(n\\).","answer":"\\(10\\)","solution":"\\(S_n=2(2^n-1)=2046\\Rightarrow2^n=1024\\Rightarrow n=10\\).","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","modelling"],"check":{"mode":"number","value":10,"tolerance":1e-06}},{"id":"IBAI-1.3-P36","level":"Challenge","prompt":"A bouncing ball starts at 3 m and each rebound reaches 70% of the previous height. Find the total vertical distance through the first 6 rebounds, including the initial drop.","answer":"\\(15.35291\\)","solution":"Initial drop is 3 m. Each of the first six rebound heights is travelled upward and downward, so add twice their sum.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","modelling"],"check":{"mode":"number","value":15.352913999999997,"tolerance":0.05}},{"id":"IBAI-1.3-P37","level":"Challenge","prompt":"Find the first integer \\(n\\ge0\\) for which \\(500(1.08)^n>650+35n\\).","answer":"\\(9\\)","solution":"A table gives \\(A_8\\approx925.47<B_8=930\\), but \\(A_9\\approx999.50>B_9=965\\), so \\(n=9\\).","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","modelling"],"check":{"mode":"number","value":9,"tolerance":1e-06}},{"id":"IBAI-1.3-P38","level":"Challenge","prompt":"A population is 12,000 and decreases 3% annually. A conservation action adds 250 individuals at the end of each year. Using a recurrence, find the population after 5 years.","answer":"\\(11482.02476\\)","solution":"Use \\(P_{n+1}=0.97P_n+250\\), starting \\(P_0=12000\\), and iterate five times. This gives approximately 11482.02.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","modelling"],"check":{"mode":"number","value":11482.0247609,"tolerance":50.0}},{"id":"IBAI-1.3-P39","level":"Challenge","prompt":"The sum of three consecutive positive geometric terms is 26 and their product is 216. Find the middle term.","answer":"\\(6\\)","solution":"Write the terms \\(6/r,6,6r\\) because their product is \\(6^3=216\\). Their sum gives \\(r+1/r=10/3\\); the middle term remains 6.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","modelling"],"check":{"mode":"number","value":6,"tolerance":1e-06}},{"id":"IBAI-1.3-P40","level":"Challenge","prompt":"A geometric sequence has \\(u_3=45\\) and \\(S_5=348.75\\), with positive ratio greater than 1. Find \\(r\\).","answer":"\\(2\\)","solution":"For \\(r=2\\), \\(a=45/4=11.25\\), and \\(S_5=11.25(1+2+4+8+16)=348.75\\). Hence \\(r=2\\).","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","modelling"],"check":{"mode":"number","value":2,"tolerance":1e-06}}],"quiz":[{"id":"IBAI-1.3-Q01","level":"Quiz","prompt":"For \\(a=4,r=3\\), find \\(u_7\\).","answer":"\\(2916\\)","solution":"\\(u_7=4(3)^6\\).","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":2916,"tolerance":1e-06}},{"id":"IBAI-1.3-Q02","level":"Quiz","prompt":"Find the ratio of \\(96,48,24,\\ldots\\).","answer":"\\(0.5\\)","solution":"Divide consecutive terms.","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":0.5,"tolerance":0.05}},{"id":"IBAI-1.3-Q03","level":"Quiz","prompt":"For \\(a=6,r=2\\), find \\(S_8\\).","answer":"\\(1530\\)","solution":"\\(S_8=6(2^8-1)\\).","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":1530,"tolerance":1e-06}},{"id":"IBAI-1.3-Q04","level":"Quiz","prompt":"Given \\(u_2=10\\), \\(u_5=80\\), find the positive ratio.","answer":"\\(2\\)","solution":"\\(r^3=8\\).","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":2,"tolerance":1e-06}},{"id":"IBAI-1.3-Q05","level":"Quiz","prompt":"Which term of \\(5,15,45,\\ldots\\) is 3645?","answer":"\\(7\\)","solution":"\\(5(3)^{n-1}=3645\\Rightarrow3^{n-1}=729=3^6\\).","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":7,"tolerance":1e-06}},{"id":"IBAI-1.3-Q06","level":"Quiz","prompt":"A value starts at 900 and decreases 12% yearly. Find it after 5 years.","answer":"\\(474.95873\\)","solution":"Use factor 0.88.","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":474.95872512,"tolerance":0.5}},{"id":"IBAI-1.3-Q07","level":"Quiz","prompt":"A population begins at 300 and grows 7% yearly. Find it after 10 years.","answer":"\\(590.14541\\)","solution":"Use \\(300(1.07)^{10}\\).","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":590.14540718687,"tolerance":0.5}},{"id":"IBAI-1.3-Q08","level":"Quiz","prompt":"How many complete years until a 10% annual depreciation leaves less than half the value?","answer":"\\(7\\)","solution":"\\(0.9^6>0.5\\), \\(0.9^7<0.5\\).","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":7,"tolerance":1e-06}},{"id":"IBAI-1.3-Q09","level":"Quiz","prompt":"A quantity doubles every 6 hours. Find the hourly growth factor.","answer":"\\(1.12246\\)","solution":"Solve \\(r^6=2\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":1.122462048309373,"tolerance":0.005}},{"id":"IBAI-1.3-Q10","level":"Quiz","prompt":"A ball rebounds to 60% of height. From 4 m, find total distance through 4 rebounds including initial drop.","answer":"\\(14.4448\\)","solution":"Add initial drop and twice each rebound height.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":14.444799999999999,"tolerance":0.05}}],"exam":[{"id":"IBAI-1.3-E01","style":"Paper 1-style short response","title":"Equipment depreciation","calculator":"GDC expected","total_marks":9,"context":"A piece of equipment is purchased for QAR 24,000 and retains 82% of its value each year.","parts":[{"label":"a","prompt":"Write a model for the value after \\(n\\) years.","marks":2,"answer":"\\(V_n=24000(0.82)^n\\)","markscheme":"M1 identifies multiplier; A1 correct model/index."},{"label":"b","prompt":"Find the value after 6 years.","marks":2,"answer":"QAR 7,296.16","markscheme":"M1 substitutes; A1 correct currency value."},{"label":"c","prompt":"Find the first complete year in which the value is below QAR 8000.","marks":3,"answer":"6 years","markscheme":"M1 forms/solves inequality; A1 continuous threshold; A1 checks first integer year."},{"label":"d","prompt":"Interpret the ratio 0.82 in context.","marks":2,"answer":"Each year the equipment retains 82% and loses 18% of the previous year’s value.","markscheme":"A1 retention; A1 loss is based on current value."}]},{"id":"IBAI-1.3-E02","style":"Paper 2-style extended response","title":"Restoration programme","calculator":"GDC expected","total_marks":12,"context":"A restoration programme plants 600 trees in year 1. Each later year it plants 1.12 times the previous year’s number.","parts":[{"label":"a","prompt":"Find the planned number in year 8.","marks":2,"answer":"1326.41 trees","markscheme":"M1 nth-term formula; A1 value."},{"label":"b","prompt":"Find the total planned over the first 8 years.","marks":3,"answer":"7379.82 trees","markscheme":"M1 geometric-sum formula; M1 substitution; A1 value."},{"label":"c","prompt":"In practice, capacity is limited to 1200 trees in any one year. Find the first year the unrestricted model exceeds capacity.","marks":3,"answer":"Year 8","markscheme":"M1 solves \\(600(1.12)^{n-1}>1200\\); A1 threshold; A1 checks adjacent years."},{"label":"d","prompt":"From that year onward, suppose planting remains at 1200 per year. Find the revised total for the first 12 years.","marks":3,"answer":"12053.41 trees","markscheme":"M1 sums unrestricted years before cap; M1 adds capped years; A1 total."},{"label":"e","prompt":"State one limitation of assuming a constant 12% increase.","marks":1,"answer":"Land, staff, budget or seedling supply may constrain growth.","markscheme":"A1 relevant contextual limitation."}]}],"bankBridge":{"course":"ib-math-ai","unit":1,"lesson":"1.3","skillKeys":["IBAI.U1.SEQUENCES","IBAI.U1.MODELING"],"visibility":"authenticated-school-access","embeddedPrivatePrompts":false},"assessmentDesign":{"practiceLevels":{"Foundation":10,"Application":10,"Reasoning":10,"Challenge":10},"quizQuestions":10,"extendedTasks":2,"calculatorPolicy":"Technology is integrated throughout, with transparent setup and interpretation."}};
